result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/toa.py", "content": "#!/usr/bin/env python3
"""Table-of-Authorities builder.

Extracts citations of the forms:
    Case: <Name> v. <Name>, <vol> C.R. <page> (<year>)
    Statute: Corv. Code s. <num>.

Deduplicates authorities (multiple pincites -> one entry), counts
citation frequency, and emits a Table of Authorities as plain text
(cases alphabetized by first party, then statutes in numeric section
order) plus a structured toa.json.
"""

from __future__ import annotations

import json
import re
import sys
from dataclasses import dataclass

CASE_RE = re.compile(
    r"Case:\s*(?P<first>[A-Z][\w'.-]+)\s+[vV]\.\s+(?P<second>[A-Z][\w'.-]+)"
    r",\s+(?P<vol>\d+)\s+C\.R\.\s+(?P<pincite>\d+)\s+\((?P<year>\d{4})\)",
    re.IGNORECASE,
)
STATUTE_RE = re.compile(r"Corv\.\s+Code\s+s\.\s+(?P<section>\d+(?:\.\d+)?)")


@dataclass(frozen=True)
class CaseCite:
    first: str
    second: str
    volume: str
    pincite: str
    year: str

    @property
    def name(self) -> str:
        return f"{self.first} v. {self.second}"

    @property
    def key(self) -> tuple:
        # Authority identity: parties + reporter volume/year, NOT the pincite.
        return (self.first, self.second, self.volume, self.year)


@dataclass(frozen=True)
class StatuteCite:
    section: str


def build_toa(text: str) -> dict:
    """Return {'cases': [...], 'statutes': [...]} sorted and counted."""
    case_counts: dict[tuple, dict] = {}
    for m in CASE_RE.finditer(text):
        cite = CaseCite(**m.groupdict())
        entry = case_counts.setdefault(
            cite.key,
            {"name": cite.name, "count": 0, "pincites": [], "first": cite.first},
        )
        entry["count"] += 1
        entry["pincites"].append(cite.pincite)

    statute_counts: dict[str, int] = {}
    for m in STATUTE_RE.finditer(text):
        sec = m.group("section")
        statute_counts[sec] = statute_counts.get(sec, 0) + 1

    cases = sorted(case_counts.values(), key=lambda e: (e["first"], e["name"]))
    statutes = sorted(statute_counts.items(), key=lambda kv: _section_key(kv[0]))

    return {
        "cases": [
            {"name": c["name"], "count": c["count"], "pincites": c["pincites"]}
            for c in cases
        ],
        "statutes": [{"section": s, "count": n} for s, n in statutes],
    }


def _section_key(section: str):
    """Numeric ordering so that 4.9 sorts before 4.10."""
    return tuple(int(p) for p in section.split("."))


def render_text(toa: dict) -> str:
    width = 58
    lines = ["TABLE OF AUTHORITIES", ""]
    lines.append("Cases")
    for c in toa["cases"]:
        lines.append(f"  {c['name']} ".ljust(width, ".") + f" {c['count']}")
    lines.append("")
    lines.append("Statutes")
    for s in toa["statutes"]:
        label = f"Corv. Code s. {s['section']} "
        lines.append(f"  {label}".ljust(width, ".") + f" {s['count']}")
    return "\n".join(lines) + "\n"


def main(argv: list[str]) -> int:
    brief_path = argv[1] if len(argv) > 1 else "brief.txt"
    text = open(brief_path, encoding="utf-8").read()
    toa = build_toa(text)
    print(render_text(toa), end="")
    with open("toa.json", "w", encoding="utf-8") as fh:
        json.dump(toa, fh, indent=2)
        fh.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"})
